public class NamespaceDetector extends LayoutDetector {
    public static final Issue MISSING_PREFIX = Issue.create("MissingPrefix", ...);
    public static final Issue RES_AUTO = Issue.create("LibraryCustomView", ...);
    @Override
    public Collection<String> getApplicableElements() { return XmlScannerConstants.ALL; }
    @Override
    public void visitElement(XmlContext context, Element element) {
        if (context.getResourceFolderType() != ResourceFolderType.LAYOUT) return;
        Project project = context.getProject();
        if (!project.isLibrary()) return;
        String pkg = project.getPackage();
        if (pkg == null) return;
        String libraryUri = SdkConstants.RESOURCE_NS_PREFIX + pkg;
        NamedNodeMap attributes = element.getAttributes();
        for (int i=0; i<attributes.getLength(); i++) {
            Attr attr = (Attr) attributes.item(i);
            String value = attr.getValue();
            if (attr.getName().startsWith("xmlns")) {
                if (value.equals(libraryUri)) {
                    report(context, attr, value);
                }
            } else {
                String namespaceUri = attr.getNamespaceURI();
                if (libraryUri.equals(namespaceUri)) {
                    report(context, attr, namespaceUri);
                }
            }
        }
    }
    private void report(XmlContext context, Attr attr, String uri) {
        context.report(RES_AUTO, attr, context.getLocation(attr),
                String.format("When using a custom view with custom attributes in a library project, use the `%1$s` namespace instead of `%2$s`.", SdkConstants.AUTO_URI, uri));
    }
}
```
